@Slf4j
public class WaitlistTable extends AbstractTableModel
{
	private final String[] cols = {"Type", "Value", "Player"};
	private final List<PendingValue> rows = new ArrayList<>();

	public void setData(List<PendingValue> pending)
	{
		rows.clear();
		if (pending != null)
		{
			rows.addAll(pending);
		}
		fireTableDataChanged();
	}

	public PendingValue getRow(int idx)
	{
		if (idx < 0 || idx >= rows.size())
		{
			return null;
		}
		return rows.get(idx);
	}

	@Override
	public int getRowCount()
	{
		return rows.size();
	}

	@Override
	public int getColumnCount()
	{
		return cols.length;
	}

	@Override
	public Object getValueAt(int rowIndex, int columnIndex)
	{
		PendingValue pv = rows.get(rowIndex);
		switch (columnIndex)
		{
			case 0:
				return pv.getType().name();
			case 1:
				long value = pv.getValue();
				//TODO get this from config
				return toSuffixString(value, "k");
			case 2:
				return pv.getSuggestedPlayer() == null ? "" : pv.getSuggestedPlayer();
		}
		return null;
	}

	@Override
	public String getColumnName(int column)
	{
		return cols[column];
	}

	@Override
	public Class<?> getColumnClass(int columnIndex)
	{
		switch (columnIndex)
		{
			case 0:
			case 2:
				return String.class;
			case 1:
				return String.class; // formatted K/M/B string
		}
		return Object.class;
	}

	@Override
	public boolean isCellEditable(int rowIndex, int columnIndex)
	{
		// Allow editing Player and Value columns
		return columnIndex == 1 || columnIndex == 2;
	}

	@Override
	public void setValueAt(Object aValue, int rowIndex, int columnIndex)
	{
		PendingValue pv = rows.get(rowIndex);
		if (columnIndex == 2)
		{
			pv.setSuggestedPlayer(aValue == null ? null : aValue.toString());
			fireTableCellUpdated(rowIndex, columnIndex);
			return;
		}
		if (columnIndex == 1)
		{
			String txt = aValue == null ? "" : aValue.toString();
			try
			{
				// Parse using default config multiplier if needed; null config will default inside formatter
				long parsed = Formats.OsrsAmountFormatter.stringAmountToLongAmount(txt, (PluginConfig) null);
				pv.setValue(parsed);
				fireTableCellUpdated(rowIndex, columnIndex);
			}
			catch (ParseException e)
			{
				log.warn("Failed to parse amount '{}' for pending value row {}", txt, rowIndex, e);
			}
		}
	}
}

package com.splitmanager.models;

import com.splitmanager.utils.Formats;
import java.awt.image.BufferedImage;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.table.AbstractTableModel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

public final class Metrics extends AbstractTableModel
{
	private final JButton removeBtn = createStyledButton("/com/splitmanager/icons/trash-solid-full.png");
	private final JButton addBtn = createStyledButton("/com/splitmanager/icons/trash-arrow-up-solid-full.png");
	private List<PlayerMetrics> rows = List.of();
	private boolean hideTotalColumn = false;

	private static JButton createStyledButton(String iconPath)
	{
		BufferedImage img = ImageUtil.loadImageResource(Metrics.class, iconPath);
		BufferedImage scaledImg = ImageUtil.resizeImage(img, 16, 16);
		JButton btn = new JButton(new ImageIcon(scaledImg));
		btn.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR));
		return btn;
	}

	public void setHideTotalColumn(boolean hide)
	{
		if (this.hideTotalColumn != hide)
		{
			this.hideTotalColumn = hide;
			fireTableStructureChanged();
		}
	}

	public boolean isHidingTotalColumn()
	{
		return hideTotalColumn;
	}

	public void setData(List<PlayerMetrics> rows)
	{
		// Sort: active first, inactive at bottom; stable within groups
		this.rows = rows.stream()
			.sorted(Comparator.comparingInt(pm -> pm.activePlayer ? 0 : 1)) // active=true → 0, inactive=false → 1
			.collect(Collectors.toList());
		fireTableDataChanged();
	}

	// Helper for renderers/editors to know if a row is active
	public boolean isRowActive(int rowIndex)
	{
		if (rowIndex < 0 || rowIndex >= rows.size())
		{
			return false;
		}
		return rows.get(rowIndex).activePlayer;
	}

	@Override
	public int getRowCount()
	{
		return rows.size();
	}

	@Override
	public int getColumnCount()
	{
		return hideTotalColumn ? 3 : 4;
	}

	@Override
	public Object getValueAt(int rowIndex, int columnIndex)
	{
		var r = rows.get(rowIndex);
		if (!hideTotalColumn)
		{
			switch (columnIndex)
			{
				case 0:
					return r.player;
				case 1:
					return Formats.OsrsAmountFormatter.toSuffixString(r.total, 'k');
				case 2:
					return Formats.OsrsAmountFormatter.toSuffixString(r.split, 'k');
				case 3:
					return r.activePlayer ? removeBtn : addBtn;
				default:
					return "";
			}
		}
		else
		{
			switch (columnIndex)
			{
				case 0:
					return r.player;
				case 1:
					return Formats.OsrsAmountFormatter.toSuffixString(r.split, 'k');
				case 2:
					return r.activePlayer ? removeBtn : addBtn;
				default:
					return "";
			}
		}
	}

	@Override
	public String getColumnName(int column)
	{
		if (!hideTotalColumn)
		{
			switch (column)
			{
				case 0:
					return "Player";
				case 1:
					return "Total";
				case 2:
					return "Split";
				case 3:
					return "X";
				default:
					return "";
			}
		}
		else
		{
			switch (column)
			{
				case 0:
					return "Player";
				case 1:
					return "Split";
				case 2:
					return "X";
				default:
					return "";
			}
		}
	}

	@Override
	public Class<?> getColumnClass(int columnIndex)
	{
		// Use Object so we can render either a JButton (active) or a JLabel (inactive) in action col
		return Object.class;
	}

	@Override
	public boolean isCellEditable(int rowIndex, int columnIndex)
	{
		int actionCol = hideTotalColumn ? 2 : 3;
		return columnIndex == actionCol;
	}

	// Accessor for renderers: raw split value for row
	public long getRawSplitAt(int rowIndex)
	{
		if (rowIndex < 0 || rowIndex >= rows.size())
		{
			return 0L;
		}
		return rows.get(rowIndex).split;
	}
}

